//! Reading and writing SRT, ASS and `WebVTT`: round trips of files the tests
//! make, conversions, encodings, tolerant reading and the timing
//! operations. No third-party subtitle file is part of the repository; a
//! folder of them can be checked with `RVP_SUBTITLE_SAMPLES`.

use rvp_subtitle::{Cue, Document, Format};

const SRT: &str = "1\r\n00:00:01,000 --> 00:00:02,500\r\nHello\r\n\r\n\
2\r\n00:00:03,000 --> 00:00:05,000\r\n<i>Two</i>\r\nlines\r\n\r\n\
3\r\n01:02:03,004 --> 01:02:04,000\r\nLast\r\n\r\n";

const ASS: &str = "[Script Info]\r\n\
; Script generated by a test\r\n\
ScriptType: v4.00+\r\n\
PlayResX: 1920\r\n\
PlayResY: 1080\r\n\
\r\n\
[V4+ Styles]\r\n\
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding\r\n\
Style: Default,Arial,48,&H00FFFFFF,&H000000FF,&H00000000,&H80000000,0,0,0,0,100,100,0,0,1,2,1,2,20,20,40,1\r\n\
Style: Sign,Georgia,36,&H0000FFFF,&H000000FF,&H00000000,&H00000000,-1,0,0,0,100,100,0,0,1,1,0,8,10,10,10,1\r\n\
\r\n\
[Events]\r\n\
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\r\n\
Dialogue: 0,0:00:01.00,0:00:02.50,Default,Ann,0,0,0,,Hello, {\\i1}world{\\i0}!\r\n\
Comment: 0,0:00:02.00,0:00:03.00,Default,,0,0,0,,a note for translators\r\n\
Dialogue: 1,0:00:03.00,0:00:05.00,Sign,,10,10,30,,{\\pos(960,100)}Two\\Nlines\r\n\
Dialogue: 0,1:02:03.00,1:02:04.00,Default,,0,0,0,Banner;10,Last\r\n\
\r\n\
[Aegisub Project Garbage]\r\n\
Video File: test.mkv\r\n";

const VTT: &str = "WEBVTT - made by a test\n\
\n\
NOTE a note\n\
\n\
STYLE\n\
::cue { color: yellow }\n\
\n\
intro\n\
00:00:01.000 --> 00:00:02.500 line:0 align:start\n\
Hello\n\
\n\
00:00:03.000 --> 00:00:05.000\n\
<v Ann>Two</v>\n\
lines &amp; more\n\
\n";

fn times(document: &Document) -> Vec<(i64, i64)> {
    document
        .cues
        .iter()
        .filter(|cue| !cue.is_comment())
        .map(|cue| (cue.start_ms, cue.end_ms))
        .collect()
}

#[test]
fn srt_ass_and_webvtt_read_back_as_they_were_written() {
    let srt = Document::parse(SRT.as_bytes(), None).expect("srt");
    assert_eq!(srt.format, Format::Srt);
    assert_eq!(srt.cues[1].text, "<i>Two</i>\nlines");
    assert_eq!(srt.write(Format::Srt), SRT);

    let ass = Document::parse(ASS.as_bytes(), None).expect("ass");
    assert_eq!(ass.format, Format::Ass);
    assert_eq!(ass.cues.len(), 4);
    assert!(ass.cues[1].is_comment());
    assert_eq!(ass.cues[0].text, "Hello, {\\i1}world{\\i0}!");
    assert_eq!(ass.cues[2].text, "{\\pos(960,100)}Two\nlines");
    assert_eq!(ass.cues[2].style.as_deref(), Some("Sign"));
    assert_eq!(ass.write(Format::Ass), ASS);

    let vtt = Document::parse(VTT.as_bytes(), Some("x.vtt")).expect("vtt");
    assert_eq!(vtt.format, Format::WebVtt);
    assert_eq!(vtt.cues.len(), 2);
    assert_eq!(
        vtt.cues[0].vtt.as_ref().map(|v| v.settings.as_str()),
        Some("line:0 align:start")
    );
    assert_eq!(vtt.write(Format::WebVtt), VTT);
}

#[test]
fn formats_convert_into_each_other() {
    let ass = Document::parse(ASS.as_bytes(), None).expect("ass");
    let srt = ass.write(Format::Srt);
    assert!(srt.starts_with("1\r\n00:00:01,000 --> 00:00:02,500\r\nHello, <i>world</i>!\r\n\r\n"));
    // The comment is left out, the override tags go, the lines stay.
    assert!(srt.contains("2\r\n00:00:03,000 --> 00:00:05,000\r\nTwo\r\nlines\r\n\r\n3\r\n"));
    let back = Document::parse(srt.as_bytes(), None).expect("srt");
    assert_eq!(times(&back), times(&ass));

    let srt = Document::parse(SRT.as_bytes(), None).expect("srt");
    let ass = srt.write(Format::Ass);
    assert!(ass.starts_with("[Script Info]\r\n"));
    assert!(ass.contains("[V4+ Styles]\r\n"));
    assert!(
        ass.contains(
            "Dialogue: 0,0:00:03.00,0:00:05.00,Default,,0,0,0,,{\\i1}Two{\\i0}\\Nlines\r\n"
        )
    );
    // ASS keeps centiseconds: 01:02:03,004 comes back as 01:02:03,000.
    let back = Document::parse(ass.as_bytes(), None).expect("ass");
    let centiseconds = |d: &Document| -> Vec<(i64, i64)> {
        times(d)
            .iter()
            .map(|(start, end)| (start / 10, end / 10))
            .collect()
    };
    assert_eq!(centiseconds(&back), centiseconds(&srt));
    assert_eq!(
        back.write(Format::Srt),
        SRT.replace("01:02:03,004", "01:02:03,000")
    );

    let vtt = Document::parse(VTT.as_bytes(), None).expect("vtt");
    let srt = vtt.write(Format::Srt);
    assert!(srt.contains("00:00:03,000 --> 00:00:05,000\r\nTwo\r\nlines & more\r\n"));
    let vtt_again = Document::parse(srt.as_bytes(), None)
        .expect("srt")
        .write(Format::WebVtt);
    assert!(vtt_again.starts_with("WEBVTT\n\n00:00:01.000 --> 00:00:02.500\nHello\n\n"));
    assert!(vtt_again.contains("lines &amp; more\n"));
}

#[test]
fn encodings_come_from_the_bom_the_label_or_a_guess() {
    let text = "1\n00:00:01,000 --> 00:00:02,000\nПривет, мир! Как дела?\n";
    let mut utf8_bom = vec![0xEF, 0xBB, 0xBF];
    utf8_bom.extend_from_slice(text.as_bytes());
    let document = Document::parse(&utf8_bom, None).expect("utf-8 bom");
    assert_eq!(
        (document.encoding, document.cues[0].text.as_str()),
        ("UTF-8", "Привет, мир! Как дела?")
    );

    let mut utf16 = vec![0xFF, 0xFE];
    for unit in text.encode_utf16() {
        utf16.extend_from_slice(&unit.to_le_bytes());
    }
    let document = Document::parse(&utf16, None).expect("utf-16");
    assert_eq!(document.encoding, "UTF-16LE");
    assert_eq!(document.cues[0].text, "Привет, мир! Как дела?");

    let (cp1251, _, _) = encoding_rs::WINDOWS_1251.encode(text);
    let named = Document::parse_with_encoding(&cp1251, "cp1251", None).expect("cp1251");
    assert_eq!(named.encoding, "windows-1251");
    assert_eq!(named.cues[0].text, "Привет, мир! Как дела?");
    let guessed = Document::parse(&cp1251, None).expect("guessed");
    assert_eq!(guessed.encoding, "windows-1251");
    assert_eq!(guessed.cues, named.cues);

    let (korean, _, _) =
        encoding_rs::EUC_KR.encode("1\n00:00:01,000 --> 00:00:02,000\n안녕하세요, 반갑습니다.\n");
    let document = Document::parse(&korean, None).expect("korean");
    assert_eq!(document.encoding, "EUC-KR");
    assert_eq!(document.cues[0].text, "안녕하세요, 반갑습니다.");

    assert!(Document::parse_with_encoding(b"", "klingon", Some("a.srt")).is_err());
}

#[test]
fn reading_is_as_tolerant_as_players_are() {
    // No indices, dots for milliseconds, LF only, blank lines and spaces
    // around, coordinates after the times, a blank line inside a cue.
    let messy = "\n\n00:00:01.5 --> 00:00:02.000 X1:10 X2:20\nOne\n\n\n\
00:00:03,000-->00:00:04,000\nTwo\n\nmore\n7\n00:00:05,000 --> 00:00:06,000\nThree   \n";
    let document = Document::parse(messy.as_bytes(), None).expect("messy");
    let texts: Vec<&str> = document.cues.iter().map(|cue| cue.text.as_str()).collect();
    assert_eq!(texts, ["One", "Two\nmore", "Three"]);
    assert_eq!(times(&document), [(1500, 2000), (3000, 4000), (5000, 6000)]);

    // WebVTT without hours, and a file named .vtt without its signature.
    let short = "00:01.000 --> 00:02.000\nShort\n";
    let document = Document::parse(short.as_bytes(), Some("film.en.vtt")).expect("vtt");
    assert_eq!(document.format, Format::WebVtt);
    assert_eq!(times(&document), [(1000, 2000)]);

    // SSA v4: its events' Format has Marked where ASS has Layer.
    let ssa = "[Script Info]\nScriptType: v4.00\n\n[V4 Styles]\nFormat: Name, Fontname\nStyle: Default,Arial\n\n\
[Events]\nFormat: Marked, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\n\
Dialogue: Marked=0,0:00:01.00,0:00:02.00,Default,,0000,0000,0000,,Old school\n";
    let document = Document::parse(ssa.as_bytes(), Some("old.ssa")).expect("ssa");
    assert_eq!(document.cues[0].text, "Old school");
    let mut written = document.clone();
    written.cues.push(Cue::new(3000, 4000, "Added"));
    let ssa_out = written.write(Format::Ass);
    assert!(ssa_out.contains(
        "Dialogue: Marked=0,0:00:01.00,0:00:02.00,Default,,0000,0000,0000,,Old school\r\n"
    ));
    assert!(ssa_out.contains("Dialogue: Marked=0,0:00:03.00,0:00:04.00,Default,,0,0,0,,Added\r\n"));

    assert!(Document::parse(b"nothing to see", None).is_err());
}

#[test]
fn sync_and_frame_rate_change_the_times() {
    let mut document = Document::parse(SRT.as_bytes(), None).expect("srt");
    document.shift(-1500);
    // The first cue would start before 0 and end at 1000: it starts at 0.
    assert_eq!(times(&document)[..2], [(0, 1000), (1500, 3500)]);
    document.shift(-1000);
    // Now it ended at 0: gone.
    assert_eq!(document.cues.len(), 2);
    assert_eq!(times(&document)[0], (500, 2500));

    // Made for 25 fps, played on 23.976: later and longer; and back.
    let mut document = Document::parse(SRT.as_bytes(), None).expect("srt");
    document.scale(25.0, 24_000.0 / 1001.0);
    let last = document.cues[2].start_ms;
    // 3 723 004 ms * 25 / (24000 / 1001) = 3 882 007.3 ms.
    assert_eq!(last, 3_882_007);
    document.scale(24_000.0 / 1001.0, 25.0);
    for (scaled, original) in times(&document)
        .iter()
        .zip(times(&Document::parse(SRT.as_bytes(), None).expect("srt")))
    {
        assert!((scaled.0 - original.0).abs() <= 1 && (scaled.1 - original.1).abs() <= 1);
    }
    document.scale(0.0, 25.0);
    document.scale(25.0, f64::NAN);
    assert_eq!(document.cues.len(), 3);

    let mut unordered = Document::new(Format::Srt);
    unordered.cues = vec![Cue::new(5000, 6000, "b"), Cue::new(1000, 2000, "a")];
    unordered.sort();
    assert_eq!(unordered.cues[0].text, "a");
    assert_eq!(unordered.cue_at(1500), Some(0));
    assert_eq!(unordered.cue_at(2000), None);
    assert_eq!(unordered.next_cue(2000), Some(1));
}

/// Every subtitle file of `RVP_SUBTITLE_SAMPLES` (free samples kept in
/// `~/rvp-reference`) reads, writes in its own format and reads
/// again to the same cues.
#[test]
fn local_samples_survive_a_round_trip() {
    let Some(folder) = std::env::var_os("RVP_SUBTITLE_SAMPLES") else {
        eprintln!("note: RVP_SUBTITLE_SAMPLES is unset; no local samples checked");
        return;
    };
    let mut checked = 0;
    let mut entries: Vec<_> = std::fs::read_dir(&folder)
        .expect("samples folder")
        .filter_map(Result::ok)
        .map(|entry| entry.path())
        .collect();
    entries.sort();
    for path in entries {
        let name = path.to_string_lossy().into_owned();
        let Some(format) = Format::from_name(&name) else {
            continue;
        };
        let bytes = std::fs::read(&path).expect("sample");
        let document =
            Document::parse(&bytes, Some(&name)).unwrap_or_else(|e| panic!("{name}: {e}"));
        let again = Document::parse(&document.to_bytes(format), Some(&name)).expect("again");
        let shown = |d: &Document| -> Vec<(i64, i64, String)> {
            d.cues
                .iter()
                .filter(|c| !c.is_comment())
                .map(|c| (c.start_ms / 10, c.end_ms / 10, c.text.clone()))
                .collect()
        };
        assert_eq!(shown(&again), shown(&document), "{name}");
        checked += 1;
    }
    eprintln!("note: {checked} local samples checked");
}
